behavior:
// Pallet — authored EUR-pallet cargo. Demonstrates the cargo geometry kind: the package geometry declares
// { kind: 'cargo', cargoKind: 'pallet' } and the host builds the part as one dynamic physics body at the
// standardized EUR pallet size (1.22 × 0.135 × 1.02 m), rendered through the instanced cargo batch as the
// slatted pallet model. Passive payload: step() is empty.

definePart({
  params: {
    // the colour is a tint over the pallet wood texture
    mass: { type: 'number', default: 20, min: 5, max: 100, step: 1, label: 'Mass (kg)', desc: 'Physical mass of the pallet itself, before anything is stacked on it.' },
    color: { type: 'color', default: '#ffffff', label: 'Color', desc: 'Tint over the pallet wood texture. White leaves it untinted.' },
  },
  step() {
  },
})
